#!/data/data/com.termux/files/usr/bin/bash
# Porting fitur kritis dari legacy-old-project ke project aktif:
# 1. LiveServer.js -> server/ (backend Socket.io, sumber data real-time)
# 2. FloatingWindowService.java -> android native overlay service (SYSTEM_ALERT_WINDOW)
# 3. AndroidManifest.xml -> tambah izin overlay + register service
# 4. FloatingLiveOverlay.js -> tambah: request overlay permission, AppState resume,
#    drag beneran (Animated.ValueXY), custom alert input
# Jalanin dari root project (~/FloatingLiveOverlayApp)

set -e
TS=$(date +%Y%m%d-%H%M%S)

echo "=== 1. Backup file yang bakal ke-timpa ==="
[ -f src/FloatingLiveOverlay.js ] && cp src/FloatingLiveOverlay.js "src/FloatingLiveOverlay.PRE-PORT-$TS.js"
[ -f android/app/src/main/AndroidManifest.xml ] && cp android/app/src/main/AndroidManifest.xml "android/app/src/main/AndroidManifest.PRE-PORT-$TS.xml"
echo "Backup dibuat (kalau ada file lama)."

echo ""
echo "=== 2. Setup folder server (backend) ==="
mkdir -p server
echo "" | base64 -d > server/LiveServer.js
echo "" | base64 -d > server/package.json
echo "" | base64 -d > server/.env.example
echo "server/LiveServer.js, package.json, .env.example dibuat"

echo ""
echo "=== 3. Setup native Android FloatingWindowService ==="
mkdir -p android/app/src/main/java/com/floatingliveoverlayapp
echo "" | base64 -d > android/app/src/main/java/com/floatingliveoverlayapp/FloatingWindowService.java
echo "FloatingWindowService.java dibuat"

echo ""
echo "=== 4. Update AndroidManifest.xml (izin overlay + register service) ==="
echo "" | base64 -d > android/app/src/main/AndroidManifest.xml
echo "AndroidManifest.xml diupdate"

echo ""
echo "=== 5. Update FloatingLiveOverlay.js (permission request, drag, custom alert) ==="
echo "" | base64 -d > src/FloatingLiveOverlay.js
echo "FloatingLiveOverlay.js diupdate"

echo ""
echo "=== Selesai. Yang berubah: ==="
echo "  + server/LiveServer.js       (backend, jalanin manual: cd server && npm install && npm start)"
echo "  + server/.env.example         (copy jadi .env, isi API key TikTok/IG/YouTube)"
echo "  + FloatingWindowService.java  (native overlay service, package: com.floatingliveoverlayapp)"
echo "  + AndroidManifest.xml         (izin SYSTEM_ALERT_WINDOW + FOREGROUND_SERVICE)"
echo "  + FloatingLiveOverlay.js      (overlay permission request, drag jalan, custom alert input)"
echo ""
echo "Catatan: server/ itu project Node.js TERPISAH, bukan bagian dari RN app."
echo "Buat jalanin: cd server && npm install && cp .env.example .env && npm start"
